const data=[['MSFT','Microsoft','Equity','NASDAQ:MSFT','Medium','Quality compounder, AI monetisation and cloud durability.','MS'],['BTC','Bitcoin','Crypto','BTCUSD','High','Macro-sensitive digital asset with high volatility.','BTC'],['ETH','Ethereum','Crypto','ETHUSD','High','Smart-contract network with protocol and regulatory risk.','ETH'],['DOGE','Dogecoin','Memecoin','DOGEUSD','Very high','Narrative asset; use strict exposure limits.','DOGE'],['QQQ','Invesco QQQ','ETF','NASDAQ:QQQ','Medium','US growth and technology factor exposure.','Q'],['CAC','CAC 40','Index','EURONEXT:PX1','Medium','France large-cap / euro-area exposure.','CAC'],['MC','LVMH','French equity','EPA:MC','Medium','Luxury franchise, China demand sensitivity.','MC'],['RKLB','Rocket Lab','Space','NASDAQ:RKLB','Very high','Pre-profit space exposure with financing and event risk.','RKLB']];
const labels={dashboard:'COMMAND CENTER',research:'RESEARCH COCKPIT',watchlist:'ACTIVE WATCHLIST',calendar:'EVENT CALENDAR',briefing:'DAILY BRIEFING',reports:'AI RESEARCH REPORTS',chat:'ANALYST COPILOT',universe:'ASSET UNIVERSE',portfolio:'PORTFOLIO LAB'};
function go(v){document.querySelectorAll('.view').forEach(x=>x.classList.remove('visible'));document.getElementById(v).classList.add('visible');document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===v));document.querySelector('#crumb').textContent=labels[v];scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>go(x.dataset.view));
const ideas=document.querySelector('#ideas');if(ideas)ideas.innerHTML=data.slice(0,4).map(a=>'<tr class="rowgo" data-asset="'+a[0]+'"><td class="assetname"><b>'+a[0]+' - '+a[1]+'</b><small>'+a[2]+'</small></td><td>'+a[5]+'</td><td><span class="badge">12-24M</span></td><td class="conviction">8.2 / 10</td><td>Research refresh</td></tr>').join('');
const wr=document.querySelector('#watchlistRows');if(wr)wr.innerHTML=data.slice(0,6).map(a=>'<tr class="rowgo" data-asset="'+a[0]+'"><td class="assetname"><b>'+a[0]+'</b><small>'+a[1]+'</small></td><td>Demo</td><td class="positive">Live soon</td><td>8.4 / 10</td><td>6.8 / 10</td><td>Review</td><td><span class="badge">Track</span></td><td>Event calendar</td></tr>').join('');
const modal=document.createElement('dialog');modal.className='hmodal';modal.innerHTML='<button class="modalclose">x</button><div id="modalBody"></div>';document.body.appendChild(modal);modal.querySelector('.modalclose').onclick=()=>modal.close();
function risk(asset){const a=data.find(x=>x[0]===asset)||data[0];modal.querySelector('#modalBody').innerHTML='<p class="eyebrow">RISK LENS - '+a[0]+'</p><h2>'+a[1]+'</h2><p>'+a[5]+'</p><div class="lens"><span>Risk label</span><b>'+a[4]+'</b><span>Time horizon</span><b>Define before exposure</b><span>Invalidation</span><b>Write a counter-thesis first</b><span>Action</span><b>Research only, no order execution</b></div><div class="actions"><a target="_blank" href="https://www.tradingview.com/symbols/'+a[3]+'/">Open TradingView</a><a target="_blank" href="https://traderepublic.com/">Open Trade Republic</a></div>';modal.showModal()}
document.addEventListener('click',e=>{const r=e.target.closest('.rowgo');if(r){risk(r.dataset.asset);return}if(e.target.matches('.textbtn,.dots'))notice('This workflow will be connected to the free data and Neon phase.')});
const universe=document.createElement('section');universe.id='universe';universe.className='view';universe.innerHTML='<div class="titlebar compact"><div><p class="eyebrow">CROSS-ASSET DISCOVERY</p><h1>Asset universe</h1><p class="sub">Research across equities, ETFs, indices, crypto, memecoins and themes.</p></div><button class="primary" id="openLocal">Create local workspace</button></div><div id="filters" class="filters"></div><div id="cards" class="cards"></div><p class="universe-note">External links never place orders. Horizon is a research workflow, not a broker.</p>';document.querySelector('main').appendChild(universe);
const nav=document.createElement('button');nav.className='nav';nav.dataset.view='universe';nav.innerHTML='<span>o</span> Asset universe';document.querySelector('.sidebar nav p').insertAdjacentElement('beforebegin',nav);nav.onclick=()=>go('universe');
const types=['All','Equity','Crypto','Memecoin','ETF','Index','French equity','Space'];document.querySelector('#filters').innerHTML=types.map((t,i)=>'<button class="filter '+(!i?'on':'')+'" data-t="'+t+'">'+t+'</button>').join('');
function draw(type='All'){document.querySelector('#cards').innerHTML=data.filter(a=>type==='All'||a[2]===type).map(a=>'<article class="card"><div class="cardtop"><span>'+a[6]+'</span><div><small>'+a[2]+'</small><h3>'+a[1]+' <em>'+a[0]+'</em></h3></div><b>'+a[4]+' risk</b></div><p>'+a[5]+'</p><i class="riskline"></i><button class="analyse" data-a="'+a[0]+'">Open risk lens</button></article>').join('');document.querySelectorAll('.analyse').forEach(x=>x.onclick=()=>risk(x.dataset.a))}draw();
document.querySelectorAll('.filter').forEach(x=>x.onclick=()=>{document.querySelectorAll('.filter').forEach(y=>y.classList.remove('on'));x.classList.add('on');draw(x.dataset.t)});
const portfolio=document.createElement('section');portfolio.id='portfolio';portfolio.className='view';portfolio.innerHTML='<div class="titlebar compact"><div><p class="eyebrow">DECISION WORKBENCH</p><h1>Portfolio lab</h1><p class="sub">Test allocation logic locally before any real-world decision.</p></div><button class="primary" id="savePlan">Save local plan</button></div><div class="lab panel"><div><h2>Risk budget</h2><input id="budget" type="range" min="1" max="10" value="5"><b id="budgetValue">5 / 10</b></div><div><h2>Investment horizon</h2><div class="horizonBtns"><button>1 month</button><button class="active">12 months</button><button>3+ years</button></div></div><div><h2>Research output</h2><p id="labResult">Balanced regime: prioritise quality and diversification. No execution signal is generated.</p></div></div>';document.querySelector('main').appendChild(portfolio);
const pnav=document.createElement('button');pnav.className='nav';pnav.dataset.view='portfolio';pnav.innerHTML='<span>+</span> Portfolio lab';nav.insertAdjacentElement('afterend',pnav);pnav.onclick=()=>go('portfolio');
document.querySelector('#budget').oninput=e=>{document.querySelector('#budgetValue').textContent=e.target.value+' / 10';document.querySelector('#labResult').textContent=e.target.value>7?'High risk budget: cap speculative exposure and document a downside plan.':'Balanced regime: prioritise quality and diversification. No execution signal is generated.'};document.querySelectorAll('.horizonBtns button').forEach(x=>x.onclick=()=>{document.querySelectorAll('.horizonBtns button').forEach(y=>y.classList.remove('active'));x.classList.add('active')});document.querySelector('#savePlan').onclick=()=>{localStorage.setItem('horizonPlan',document.querySelector('#budget').value);notice('Portfolio lab saved locally')};
function login(){modal.querySelector('#modalBody').innerHTML='<p class="eyebrow">LOCAL WORKSPACE</p><h2>Save research on this device.</h2><p>Free mode. No online account or email is created yet.</p><input id="name" placeholder="Display name"><button class="primary" id="saveName">Start workspace</button>';modal.showModal();modal.querySelector('#saveName').onclick=()=>{const n=document.querySelector('#name').value||'Research member';localStorage.setItem('horizonUser',n);document.querySelector('.user b').textContent=n;modal.close();notice('Local workspace created')}}document.querySelector('#openLocal').onclick=login;document.querySelector('.user').onclick=login;if(localStorage.horizonUser)document.querySelector('.user b').textContent=localStorage.horizonUser;
function notice(msg){let n=document.querySelector('.toast');if(!n){n=document.createElement('div');n.className='toast';document.body.appendChild(n)}n.textContent=msg;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),2200)}
document.querySelector('.search').onclick=()=>{modal.querySelector('#modalBody').innerHTML='<p class="eyebrow">COMMAND CENTER</p><h2>Jump to a workspace</h2><button class="cmd" data-v="universe">Browse asset universe</button><button class="cmd" data-v="portfolio">Open portfolio lab</button><button class="cmd" data-v="research">Open research cockpit</button><button class="cmd" data-v="chat">Ask Analyst Copilot</button>';modal.showModal();modal.querySelectorAll('.cmd').forEach(x=>x.onclick=()=>{modal.close();go(x.dataset.v)})};
document.querySelector('#chatForm')?.addEventListener('submit',e=>{e.preventDefault();const i=document.querySelector('#chatInput'),q=i.value.trim();if(!q)return;document.querySelector('#messages').insertAdjacentHTML('beforeend','<div class="message" style="margin:16px 0 0 auto;background:#203d34"><small>YOU</small><p>'+q.replace(/</g,'&lt;')+'</p></div><div class="message bot" style="margin-top:14px"><small>COPILOT</small><p>Demo answer: Horizon would organise source-backed facts, catalysts, counter-thesis and risks here. Connect market data and an AI backend to make this live.</p></div>');i.value=''});
const s=document.createElement('style');s.textContent='.filters{display:flex;gap:8px;flex-wrap:wrap;margin:4px 0 18px}.filter,.horizonBtns button{border:1px solid var(--line);background:#0c1a17;color:#a5b5af;padding:8px 11px;border-radius:16px;font-size:11px}.filter.on,.horizonBtns .active{background:#213d31;color:var(--green);border-color:#426a58}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.card{background:var(--panel);border:1px solid var(--line);padding:18px;border-radius:6px}.cardtop{display:flex;gap:10px;align-items:start}.cardtop>span{display:grid;place-items:center;width:34px;height:34px;background:#1b3a30;color:var(--lime);font-weight:bold;border-radius:8px}.cardtop small{font:9px DM Mono;color:var(--muted)}.card h3{font-size:14px;margin:4px 0}.card h3 em{font:10px DM Mono;color:var(--muted);font-style:normal}.cardtop b{margin-left:auto;font:9px DM Mono;background:#3c311d;color:var(--yellow);padding:4px;border-radius:3px}.card p{font-size:11px;line-height:1.5;min-height:48px;color:#aebbb7}.riskline{display:block;height:4px;background:linear-gradient(90deg,var(--green) 0 55%,var(--yellow) 55% 78%,var(--red) 78%)}.analyse,.actions a{background:transparent;border:0;color:var(--green);font-size:10px;padding:12px 0 0;text-decoration:none}.hmodal{width:min(520px,calc(100vw - 28px));background:#10221e;border:1px solid #45745f;color:var(--ink);padding:28px;border-radius:8px}.hmodal::backdrop{background:#010807cc}.modalclose{float:right;background:transparent;border:0;color:var(--muted);font-size:20px}.hmodal h2{font-size:24px;margin:0 0 12px}.hmodal p{font-size:12px;line-height:1.55;color:#b1c0ba}.lens{display:grid;grid-template-columns:1fr 1.3fr;border-top:1px solid var(--line);margin:18px 0}.lens span,.lens b{font-size:11px;padding:10px 0;border-bottom:1px solid var(--line)}.lens span{color:var(--muted)}.actions{display:flex;gap:16px}.actions a,.cmd{color:var(--green);font-size:11px}.cmd{display:block;width:100%;text-align:left;border:0;border-bottom:1px solid var(--line);background:#132a24;padding:12px}.lab{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}.lab h2{font-size:15px}.lab input{accent-color:var(--green);width:100%}.lab b{display:block;margin-top:10px;color:var(--lime)}.lab p{font-size:12px;line-height:1.55;color:#b6c3bd}.toast{position:fixed;right:22px;bottom:22px;background:#18362c;border:1px solid #4e816a;padding:12px;color:#d6eee2;font-size:12px;border-radius:5px;opacity:0;transform:translateY(15px);transition:.2s}.toast.show{opacity:1;transform:none}.universe-note{font-size:10px;color:var(--muted);margin-top:16px}@media(max-width:950px){.cards{grid-template-columns:repeat(2,1fr)}.lab{grid-template-columns:1fr}}@media(max-width:600px){.cards{grid-template-columns:1fr}}';document.head.appendChild(s);
